package dominoes

// Domino represents a single domino tile with two halves.
type Domino [2]int

// MakeChain computes a way to order the given dominoes so that they form a
// correct domino chain: the dots on one half of a stone match the dots on the
// neighboring half of an adjacent stone, and the dots on the two halves which
// don't have a neighbor (the first and last stone) match each other.
//
// It returns the chain and true if one exists, or nil and false otherwise.
func MakeChain(input []Domino) ([]Domino, bool) {
	n := len(input)
	switch {
	case n == 0:
		return []Domino{}, true
	case n == 1:
		if input[0][0] == input[0][1] {
			return []Domino{input[0]}, true
		}
		return nil, false
	}

	// Necessary condition: the chain is a closed loop (an Eulerian circuit),
	// so every value must appear an even number of times.
	degree := make(map[int]int)
	for _, d := range input {
		degree[d[0]]++
		degree[d[1]]++
	}
	for _, v := range degree {
		if v%2 != 0 {
			return nil, false
		}
	}

	// Any valid chain is a cycle, so it can be rotated to start with any
	// domino of the set. Try the first domino in both orientations and
	// search for a full chain with backtracking.
	used := make([]bool, n)
	chain := make([]Domino, 0, n)

	var dfs func(free int) bool
	dfs = func(free int) bool {
		if len(chain) == n {
			// The chain is closed if the free end matches the start.
			return free == chain[0][0]
		}
		for i := 0; i < n; i++ {
			if used[i] {
				continue
			}
			d := input[i]
			if d[0] == free {
				used[i] = true
				chain = append(chain, d)
				if dfs(d[1]) {
					return true
				}
				chain = chain[:len(chain)-1]
				used[i] = false
			} else if d[1] == free {
				used[i] = true
				chain = append(chain, Domino{d[1], d[0]})
				if dfs(d[0]) {
					return true
				}
				chain = chain[:len(chain)-1]
				used[i] = false
			}
		}
		return false
	}

	start := input[0]
	used[0] = true
	chain = append(chain, start)
	if dfs(start[1]) {
		return chain, true
	}
	chain = chain[:0]
	used[0] = false

	// Try the first domino reversed (only if it is not a double).
	if start[0] != start[1] {
		used[0] = true
		chain = append(chain, Domino{start[1], start[0]})
		if dfs(start[0]) {
			return chain, true
		}
	}
	return nil, false
}

